CREATE TABLE `commissions` (
  `id` varchar(64) NOT NULL,
  `artist_id` varchar(64) NOT NULL,
  `client_id` varchar(64) NOT NULL,
  `title` varchar(200) NOT NULL,
  `description` text NOT NULL DEFAULT '',
  `reference_image` longtext NOT NULL DEFAULT '',
  `status` enum('pending','active','done','declined') NOT NULL DEFAULT 'pending',
  `current_stage` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `stage_status` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT json_array(0,0,0,0,0) CHECK (json_valid(`stage_status`)),
  `client_approval` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT json_array(0,0,0,0,0) CHECK (json_valid(`client_approval`)),
  `stage_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT json_array() CHECK (json_valid(`stage_data`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

